import {base,seed,loadDB,saveDB,KEY} from './store.js';
import {defaults,validateSettings,validateName,assignFallbacks,cutoff,startTime,remaining,whatsappLink} from './rules.js';
const $=s=>document.querySelector(s), app=$('#app'), drawer=$('#drawer');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>(Number(v)/100).toLocaleString('de-DE',{style:'currency',currency:'EUR'});
const uid=()=>crypto.randomUUID();
let db=loadDB();
let selected='lette',tab='summary',scope='upcoming',search='',filter='',dirty=false;
function persist(){try{saveDB(db);}catch{toast('Speicher nicht verfügbar – Änderungen gelten nur bis zum Neuladen.');}}
const event=()=>db.events.find(ev=>ev.id===selected)||db.events[0];
const orders=(ev=event())=>db.orders.filter(o=>o.eventId===ev.id);
const count=(t,ev=event())=>orders(ev).filter(o=>o.typeId===t.id).length;
const revenue=ev=>orders(ev).reduce((s,o)=>s+o.amount,0);
const badge=status=>`<span class="status ${status==='draft'?'draft':status==='paused'?'off':''}">${{published:'● Veröffentlicht',draft:'○ Entwurf',paused:'Ⅱ Pausiert'}[status]||status}</span>`;
const btn=(label,action,primary=false)=>`<button type="button" class="btn ${primary?'primary':''}" data-action="${action}">${label}</button>`;
const field=(label,name,value,type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const check=(label,name,value)=>`<label class="check"><input name="${name}" type="checkbox" ${value?'checked':''}>${label}</label>`;
const metric=(label,value,note='',accent=false)=>`<div class="metric"><small>${label}</small><strong class="${accent?'accent':''}">${value}</strong><span>${note}</span></div>`;
const card=(title,body,actions='')=>`<section class="card"><div class="card-head"><h3>${title}</h3><div class="actions">${actions}</div></div><div class="card-body">${body}</div></section>`;
const savebar=()=>`<div class="savebar"><span id="save-status">Alle Änderungen gespeichert · nur lokal</span><button class="btn primary" type="submit">Änderungen speichern</button></div>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function navigate(hash){if(dirty&&!confirm('Ungespeicherte Änderungen verwerfen?'))return;dirty=false;location.hash=hash;}
function openDialog(title,body,onSubmit,submit='Speichern'){drawer.innerHTML=`<form id="dialog-form"><div class="dialog-head"><h2 id="dialog-title">${title}</h2><button type="button" class="close" data-close aria-label="Schließen">×</button></div><div class="dialog-body">${body}<p class="error" id="dialog-error" role="alert"></p></div><div class="dialog-foot"><button type="button" class="btn ghost" data-close>Abbrechen</button><button class="btn primary">${submit}</button></div></form>`;drawer.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>drawer.close());$('#dialog-form').onsubmit=e=>{e.preventDefault();try{onSubmit(new FormData(e.target),e.target);}catch(err){$('#dialog-error').textContent=err.message;}};drawer.showModal();}
function done(message){persist();drawer.close();render();toast(message);}
function eventRows(){const list=db.events.filter(ev=>{const datePast=ev.date<'2026-09-23';return (scope==='past'?datePast:!datePast)&&(!filter||ev.status===filter)&&(`${ev.title} ${ev.venue}`.toLowerCase().includes(search.toLowerCase()));});return list.length?list.map(ev=>{const n=orders(ev).length;return `<tr><td><div class="event-cell"><div class="date"><b>${ev.date.slice(8)}</b><small>${new Date(ev.date+'T12:00').toLocaleDateString('de-DE',{month:'short'})}</small></div><div><a class="title-link" href="#event/${ev.id}/summary">${esc(ev.title)}</a><small>${esc(ev.venue)} · ${ev.date.split('-').reverse().join('.')} · ${ev.start} Uhr</small></div></div></td><td>${badge(ev.status)}</td><td class="capacity"><div><b>${n} verkauft</b><span>${Math.max(0,ev.capacity-n)} frei</span></div><div class="bar"><span style="width:${ev.capacity?100*n/ev.capacity:0}%"></span></div></td><td class="money">${money(revenue(ev))}</td><td><div class="row-actions"><a class="btn ghost" href="#event/${ev.id}/edit">Bearbeiten</a><button class="btn ghost" data-duplicate="${ev.id}" aria-label="${esc(ev.title)} duplizieren">Duplizieren</button></div></td></tr>`;}).join(''):'<tr><td colspan="5" class="empty">Keine passenden Events gefunden.</td></tr>';}
function dashboard(overview=false){const sold=db.orders.length;app.innerHTML=`<div class="page-head"><div><span class="eyebrow">DEINE ABENDE. DEIN ÜBERBLICK.</span><h1>${overview?'WILLKOMMEN AN DER THEKE.':'EVENTS & TICKETS.'}</h1><p>Planen, verkaufen, gemeinsam spielen. Alles an einem Ort.</p></div>${btn('+ Event erstellen','new',true)}</div><div class="metrics">${metric('Kommende Events',db.events.filter(ev=>ev.date>='2026-09-23').length,'inklusive Entwürfe')}${metric('Verkaufte Teamtickets',sold,'aus lokalen Demo-Buchungen')}${metric('Umsatz',money(db.orders.reduce((s,o)=>s+o.amount,0)),'Demo · keine echten Zahlungen',true)}${metric('Warteliste',db.waiters.length,'Teams warten auf einen Platz')}</div><section class="card"><div class="card-head"><div class="tabs"><button data-scope="upcoming" class="${scope==='upcoming'?'active':''}">Kommende Events</button><button data-scope="past" class="${scope==='past'?'active':''}">Vergangene Events</button></div><span class="subtle">${db.events.length} Events insgesamt</span></div><div class="toolbar"><input class="search" id="search" type="search" placeholder="Event oder Location suchen …" aria-label="Events suchen" value="${esc(search)}"><select id="status-filter" aria-label="Eventstatus"><option value="">Alle Status</option><option value="published">Veröffentlicht</option><option value="draft">Entwurf</option><option value="paused">Pausiert</option></select><span class="subtle">Tipp: Events duplizieren und nur den Termin ändern.</span></div><div class="table-wrap"><table><thead><tr><th>VERANSTALTUNG</th><th>STATUS</th><th>TEAMTICKETS</th><th>UMSATZ</th><th>AKTIONEN</th></tr></thead><tbody id="event-rows">${eventRows()}</tbody></table></div></section><p class="footnote">Die Vorschau arbeitet mit erfundenen Bestellungen. Deine Änderungen werden nur in diesem Browser gespeichert.</p>`;$('#status-filter').value=filter;$('#search').oninput=e=>{search=e.target.value;$('#event-rows').innerHTML=eventRows();};$('#status-filter').onchange=e=>{filter=e.target.value;$('#event-rows').innerHTML=eventRows();};}
const tabs=[['summary','Überblick'],['reports','Auswertungen'],['edit','Event & Tickets'],['settings','Teilnahme & Regeln'],['orders','Bestellungen & Einlass'],['waitlist','Warteliste'],['mails','E-Mails & Reminder'],['confirmation','Bestätigung & Ticket'],['form','Buchungsformular'],['quiz','Quizvorbereitung']];
function shell(){const ev=event();app.innerHTML=`<a class="back" href="#events">← Alle Events</a><div class="event-head"><div class="event-icon">LIVE</div><div><h1>${esc(ev.title)}</h1><p class="subtle">${ev.date.split('-').reverse().join('.')} · ${ev.start}–${ev.end} Uhr · ${esc(ev.venue)}</p></div><div class="actions">${badge(ev.status)}${btn('Duplizieren','duplicate')}${btn('Eventvorschau ↗','preview')}${btn(ev.status==='published'?'Verkauf pausieren':'Veröffentlichen',ev.status==='published'?'pause':'publish',true)}</div></div><div class="layout"><aside class="side"><nav aria-label="Eventbereiche"><label>VERANSTALTUNG</label>${tabs.map(([key,label])=>`<a href="#event/${ev.id}/${key}" class="${tab===key?'active':''}" ${tab===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav>${btn('+ Bestellung anlegen','order')}</aside><section class="content" id="content"></section></div>`;const views={settings:settingsView,summary,edit,orders:orderView,reports,waitlist,mails,confirmation,form:formView,quiz};(views[tab]||summary)();}
function summary(){const ev=event(),n=orders().length;$('#content').innerHTML=`<h2>DEIN EVENT AUF EINEN BLICK.</h2><div class="metrics">${metric('Teamtickets',n,`von ${ev.capacity} Teamtickets`)}${metric('Umsatz',money(revenue(ev)),'Demo',true)}${metric('Eingecheckt',orders().filter(o=>o.checked).length,'Teams vor Ort')}${metric('Warteliste',db.waiters.filter(w=>w.eventId===ev.id).length,'wartende Teams')}</div>${card('Bereit für den nächsten Quizabend',`<div class="two-col"><div><h2>${Math.max(0,ev.capacity-n)} TEAMPLÄTZE FREI.</h2><p class="subtle" style="margin-top:12px">${esc(ev.venue)} · ${ev.date.split('-').reverse().join('.')}<br>Einlass ${ev.doors} Uhr · Beginn ${ev.start} Uhr</p><div class="bar"><span style="width:${100*n/Math.max(1,ev.capacity)}%"></span></div></div><div><h3>Die nächsten Schritte</h3><p class="subtle" style="margin:12px 0">Event pflegen, Tickets prüfen und Teams für die Quiz-App vorbereiten.</p><a class="btn primary" href="#event/${ev.id}/quiz">Zur Quizvorbereitung →</a></div></div>`)}${card('Event teilen',`<p class="subtle">Lokaler Vorschaulink für dieses Event</p><code>${esc(location.origin+location.pathname+'#event/'+ev.id+'/summary')}</code><div class="hint">Im fertigen System führt der öffentliche Verkaufslink auf www.kneipenkoenig.de. Diese Manager-Vorschau ist kein öffentlicher Verkaufslink.</div>`,btn('Vorschaulink kopieren','copy'))}${card('Ticketarten',ev.tickets.map(t=>`<div class="inline-chart"><label>${esc(t.name)}</label><div class="bar"><span style="width:${100*count(t)/Math.max(1,t.capacity)}%"></span></div><b>${count(t)}/${t.capacity}</b></div>`).join(''))}`;}
function edit(){const ev=event();$('#content').innerHTML=`<h2>EVENT & TICKETS.</h2><form id="event-form">${card('Veranstaltungsdaten',`<div class="form-grid">${field('Eventname *','title',ev.title,'text','required maxlength="150" class="wide"')}${field('Location *','venue',ev.venue,'text','required maxlength="150"')}${field('Datum *','date',ev.date,'date','required')}${field('Einlass','doors',ev.doors,'time','required')}${field('Beginn *','start',ev.start,'time','required')}${field('Ende *','end',ev.end,'time','required')}${field('Adresse','address',ev.address,'text','maxlength="250"')}</div><p class="footnote">Zeitzone: Europe/Berlin · Beispiel: Beginn und Ende am selben Tag.</p>`)}${card('Eventseite',`<label class="field"><span>Beschreibung</span><textarea name="description" maxlength="5000">${esc(ev.description)}</textarea></label><p class="footnote">Die Vorschau zeigt Text. Bildauswahl und Rich-Text-Editor folgen bei der echten Manager-Anbindung.</p>`)}<section class="card"><div class="card-head"><h3>Ticketarten & Kontingente</h3><div class="actions">${btn('+ Gruppe','group')}${btn('+ Bundle','bundle')}${btn('+ Ticketart','ticket',true)}</div></div>${ev.tickets.map(t=>`<div class="ticket-item"><div class="grow"><strong>${esc(t.name)}</strong><p>Bis ${t.players} Personen · ${esc(t.description)}</p></div><div class="capacity"><div><span>${count(t)} verkauft</span><span>${t.capacity-count(t)} frei</span></div><div class="bar"><span style="width:${100*count(t)/Math.max(1,t.capacity)}%"></span></div></div><strong class="money">${money(t.price)}</strong><button type="button" class="btn" data-ticket="${t.id}">Bearbeiten</button></div>`).join('')}<div class="card-body"><div class="form-grid">${field('Gesamtkapazität · Teamtickets','capacity',ev.capacity,'number','min="0" max="10000" required step="1"')}<div class="hint" style="margin:0">Eventlimit und Ticketartlimit gelten gemeinsam. Eine Gruppe kann ein zusätzliches gemeinsames Kontingent begrenzen.</div></div>${ev.groups.map(g=>`<div class="field-row"><span>${esc(g.name)} <small class="subtle">· gemeinsames Limit ${g.capacity}</small></span><button type="button" class="link" data-group="${g.id}">Gruppe bearbeiten</button></div>`).join('')}${ev.bundles.map(b=>`<div class="field-row"><span>${esc(b.name)} · ${money(b.price)}</span><button type="button" class="link" data-bundle="${b.id}">Bundle bearbeiten</button></div>`).join('')}</div></section>${card('Verkauf & Teilnahme',`<div class="form-grid">${field('Verkaufsstart','saleStart',ev.saleStart,'date','required')}${field('Verkaufsende','saleEnd',ev.saleEnd,'date','required')}${check('Barzahlung vor Ort erlauben','cash',ev.cash)}${check('Warteliste bei Ausverkauf aktivieren','waitlist',ev.waitlist)}</div>`)}${savebar()}</form>`;bindSave('#event-form',f=>{const capacity=Number(f.get('capacity'));if(capacity<orders().length)throw Error('Das Eventlimit darf nicht unter den bereits ausgestellten Tickets liegen.');if(f.get('end')<=f.get('start'))throw Error('Das Ende muss in diesem Entwurf nach dem Beginn liegen.');if(f.get('saleEnd')<f.get('saleStart'))throw Error('Verkaufsende liegt vor Verkaufsstart.');for(const key of ['title','venue','date','doors','start','end','address','description','saleStart','saleEnd'])ev[key]=String(f.get(key)).trim();ev.capacity=capacity;ev.cash=f.has('cash');ev.waitlist=f.has('waitlist');});}
function bindSave(selector,save){const form=$(selector);form.addEventListener('input',()=>{dirty=true;if($('#save-status'))$('#save-status').textContent='Ungespeicherte Änderungen';});form.onsubmit=e=>{e.preventDefault();try{save(new FormData(form));dirty=false;persist();render();toast('Änderungen lokal gespeichert.');}catch(err){toast(err.message);}};}
function duplicate(ev){openDialog('EVENT DUPLIZIEREN',`<p>Die Eventeinstellungen werden als neuer Entwurf übernommen. Bestellungen, Zahlungen, Warteliste, Check-ins und Ticketcodes werden nicht kopiert.</p><div class="form-grid">${field('Neuer Eventname *','title',ev.title+' – Kopie','text','required maxlength="150"')}${field('Neuer Termin *','date','','date','required')}${field('Beginn','start',ev.start,'time','required')}${field('Ende','end',ev.end,'time','required')}</div><hr class="divider">${check('Ticketarten, Gruppen und Bundles übernehmen','tickets',true)}${check('Bestätigung und Formular übernehmen','content',true)}${check('Reminder-Vorlagen übernehmen','mails',true)}<div class="hint">Verkaufszeitraum und Quizsession werden nicht übernommen. Vor Veröffentlichung bitte neu prüfen.</div>`,f=>{if(f.get('end')<=f.get('start'))throw Error('Ende muss nach Beginn liegen.');const copy=structuredClone(ev);copy.id=uid();copy.title=String(f.get('title')).trim();copy.date=String(f.get('date'));copy.start=String(f.get('start'));copy.end=String(f.get('end'));copy.status='draft';copy.saleStart='';copy.saleEnd='';const ids=new Map(copy.tickets.map(t=>[t.id,uid()]));copy.tickets.forEach(t=>t.id=ids.get(t.id));copy.groups.forEach(g=>{g.id=uid();g.ticketIds=g.ticketIds.map(id=>ids.get(id));});copy.bundles.forEach(b=>{b.id=uid();b.items=b.items.map(i=>({...i,ticketId:ids.get(i.ticketId)}));});copy.fields.forEach(x=>{if(!x.locked)x.id=uid();});copy.mails.forEach(m=>m.id=uid());if(!f.has('tickets')){copy.tickets=[];copy.groups=[];copy.bundles=[];}if(!f.has('content')){copy.confirmation=structuredClone(db.globalConfirmation);copy.fields=structuredClone(db.globalFields);}if(!f.has('mails'))copy.mails=[];db.events.push(copy);done('Event als neuen Entwurf angelegt.');navigate('event/'+copy.id+'/edit');},'Als Entwurf duplizieren');}
function ticketDialog(id){const ev=event(),t=ev.tickets.find(t=>t.id===id)||{name:'',description:'',price:4800,capacity:20,players:6,min:1,max:5,status:'sale',showRemaining:true};openDialog(id?'TICKETART BEARBEITEN':'NEUE TICKETART',`<div class="form-grid">${field('Ticketname *','name',t.name,'text','required maxlength="80"')}${field('Preis pro Ticket (€) *','price',(t.price/100).toFixed(2),'number','min="0" max="10000" step="0.01" required')}${field('Kontingent *','capacity',t.capacity,'number',`min="${id?count(t):0}" max="10000" step="1" required`)}${field('Maximale Teamgröße *','players',t.players,'number','min="1" max="100" step="1" required')}</div><div class="hint">Ein Teamticket = ein Tisch / ein Team-QR. Keine geschätzten Paymentgebühren: der angegebene Preis ist der Demo-Endpreis.</div><details open><summary>Weitere Einstellungen</summary><label class="field"><span>Beschreibung</span><textarea name="description" maxlength="500">${esc(t.description)}</textarea></label><div class="form-grid" style="margin-top:18px">${field('Minimum je Bestellung','min',t.min,'number','min="1" max="100" required')}${field('Maximum je Bestellung','max',t.max,'number','min="1" max="100" required')}<label class="field"><span>Verkaufsstatus</span><select name="status"><option value="sale" ${t.status==='sale'?'selected':''}>Im Verkauf</option><option value="hidden" ${t.status==='hidden'?'selected':''}>Verborgen</option><option value="paused" ${t.status==='paused'?'selected':''}>Pausiert</option></select></label>${check('Restmenge anzeigen','remaining',t.showRemaining)}</div></details>`,f=>{if(Number(f.get('min'))>Number(f.get('max')))throw Error('Minimum darf Maximum nicht überschreiten.');const row={id:id||uid(),name:String(f.get('name')).trim(),price:Math.round(Number(f.get('price'))*100),capacity:Number(f.get('capacity')),players:Number(f.get('players')),description:String(f.get('description')),min:Number(f.get('min')),max:Number(f.get('max')),status:String(f.get('status')),showRemaining:f.has('remaining')};if(id)ev.tickets[ev.tickets.findIndex(t=>t.id===id)]=row;else ev.tickets.push(row);done('Ticketart gespeichert.');});}
function groupDialog(id){const ev=event(),g=ev.groups.find(g=>g.id===id)||{name:'',capacity:ev.capacity,ticketIds:[]};openDialog('TICKETGRUPPE',`<p>Eine Gruppe fasst Ticketarten zusammen und kann deren gemeinsames Kontingent begrenzen.</p><div class="form-grid">${field('Gruppenname *','name',g.name,'text','required maxlength="80"')}${field('Gemeinsames Limit *','capacity',g.capacity,'number','min="0" max="10000" required')}</div><hr class="divider">${ev.tickets.map(t=>check(esc(t.name),'type:'+t.id,g.ticketIds.includes(t.id))).join('')}`,f=>{const ticketIds=ev.tickets.filter(t=>f.has('type:'+t.id)).map(t=>t.id);if(!ticketIds.length)throw Error('Mindestens eine Ticketart auswählen.');if(Number(f.get('capacity'))<orders().filter(o=>ticketIds.includes(o.typeId)).length)throw Error('Limit liegt unter bereits ausgestellten Tickets.');const row={id:id||uid(),name:String(f.get('name')).trim(),capacity:Number(f.get('capacity')),ticketIds};if(id)ev.groups[ev.groups.findIndex(x=>x.id===id)]=row;else ev.groups.push(row);done('Ticketgruppe gespeichert.');});}
function bundleDialog(id){const ev=event(),b=ev.bundles.find(b=>b.id===id)||{name:'',price:8000,items:[]};openDialog('TICKET-BUNDLE',`<p>Mehrere Teamtickets zu einem Paketpreis. Die enthaltenen Ticketarten verbrauchen weiterhin ihr eigenes Kontingent.</p><div class="form-grid">${field('Bundle-Name *','name',b.name,'text','required maxlength="80"')}${field('Paketpreis (€) *','price',(b.price/100).toFixed(2),'number','min="0" max="10000" step="0.01" required')}</div><hr class="divider">${ev.tickets.map(t=>`<div style="margin:15px 0">${field(esc(t.name),'type:'+t.id,b.items.find(i=>i.ticketId===t.id)?.quantity||0,'number','min="0" max="20" step="1" required')}</div>`).join('')}`,f=>{const items=ev.tickets.map(t=>({ticketId:t.id,quantity:Number(f.get('type:'+t.id))})).filter(i=>i.quantity>0);if(!items.length)throw Error('Mindestens ein enthaltenes Ticket festlegen.');const row={id:id||uid(),name:String(f.get('name')).trim(),price:Math.round(Number(f.get('price'))*100),items};if(id)ev.bundles[ev.bundles.findIndex(x=>x.id===id)]=row;else ev.bundles.push(row);done('Bundle gespeichert.');});}
function orderView(){const ev=event();$('#content').innerHTML=`<h2>BESTELLUNGEN & EINLASS.</h2><section class="card"><div class="card-head"><h3>${orders().length} ausgestellte Teamtickets</h3><div class="actions">${btn('Einlassliste exportieren','export')}${btn('+ Bestellung','order',true)}</div></div><div class="toolbar"><input id="order-search" type="search" placeholder="Name, Team, E-Mail oder Bestellnummer …" aria-label="Bestellungen suchen"></div><div class="table-wrap"><table><thead><tr><th>TEAM / KONTAKT</th><th>TICKET</th><th>ZAHLUNG</th><th>EINLASS / AKTIONEN</th></tr></thead><tbody id="order-rows"></tbody></table></div></section><p class="footnote">Barzahlung und Einlass sind unabhängig. Einchecken bestätigt keine Zahlung.</p>`;const draw=q=>{$('#order-rows').innerHTML=orders().filter(o=>[o.name,o.team,o.email,o.id].join(' ').toLowerCase().includes(q.toLowerCase())).map(o=>`<tr><td><strong>${esc(o.team||'Teamname fehlt')}</strong><small>${esc(o.name)} · ${esc(o.email)}</small><button class="link" data-team-edit="${o.id}">Teamname ändern</button></td><td>${esc(ev.tickets.find(t=>t.id===o.typeId)?.name||'Ticket')}<small>${esc(o.id)} · bis ${o.ticketCapacity} Plätze</small></td><td>${money(o.amount)}<small>${o.payment==='cash-open'?'Barzahlung offen':'Demo bestätigt'}</small></td><td>${ev.settings.checkin?`<button class="btn ${o.checked?'ghost':'primary'}" data-check="${o.id}">${o.checked?'✓ Vor Ort · zurücksetzen':'Einchecken'}</button>`:'Check-in deaktiviert'}<a class="btn ghost" href="index.html#manage/${o.editToken}">Namenslink öffnen ↗</a></td></tr>`).join('')||'<tr><td colspan="4" class="empty">Keine Bestellungen vorhanden.</td></tr>';};draw('');$('#order-search').oninput=e=>draw(e.target.value);}
function orderDialog(){const ev=event();if(!ev.tickets.length){toast('Bitte zuerst eine Ticketart anlegen.');return;}openDialog('DEMO-BESTELLUNG',`<p>Ein Teamticket anlegen. Die tatsächliche Personenzahl wird nicht erfasst.</p><div class="form-grid">${field('Name *','name','','text','required maxlength="100"')}${field('E-Mail *','email','','email','required')}${field('Teamname · optional','team','','text','minlength="2" maxlength="20"')}<label class="field"><span>Ticketart</span><select name="type">${ev.tickets.map(t=>`<option value="${t.id}">${esc(t.name)} · ${money(t.price)}</option>`).join('')}</select></label>${check('Barzahlung noch offen','cash',false)}</div>`,f=>{const t=ev.tickets.find(t=>t.id===f.get('type'));if(!remaining(db,ev,t))throw Error('Das Kontingent ist ausgeschöpft.');const team=validateName(db,ev.id,f.get('team'));db.orders.push({id:'DEMO-'+uid().slice(0,8),eventId:ev.id,typeId:t.id,name:String(f.get('name')).trim(),email:String(f.get('email')).trim(),team,ticketCapacity:t.players,amount:t.price,payment:f.has('cash')?'cash-open':'confirmed',checked:false,quiz:false,editToken:uid()});assignFallbacks(db);done('Demo-Bestellung angelegt.');});}
function reports(){const ev=event();$('#content').innerHTML=`<h2>AUSWERTUNGEN.</h2><div class="metrics">${metric('Teamtickets',orders().length)}${metric('Gebuchte Plätze',orders().reduce((s,o)=>s+o.ticketCapacity,0))}${metric('Umsatz',money(revenue(ev)),'Demo',true)}${metric('Check-in',orders().filter(o=>o.checked).length)}</div>${card('Verteilung nach Ticketart',ev.tickets.map(t=>`<div class="inline-chart"><label>${esc(t.name)}</label><div class="bar"><span style="width:${100*count(t)/Math.max(1,orders().length)}%"></span></div><b>${count(t)}</b></div>`).join(''),btn('Bericht drucken','print'))}<p class="footnote">Alle Werte werden aus den lokalen Demo-Bestellungen berechnet. Website-Aufrufe und zeitliche Umsatzverläufe benötigen später echte Analytics-Daten.</p>`;}
function waitlist(){const ev=event(),list=db.waiters.filter(w=>w.eventId===ev.id);$('#content').innerHTML=`<h2>WARTELISTE.</h2>${card('Kontakt aufnehmen',list.length?list.map(w=>{const text=`Hallo ${w.name}, für ${ev.title} am ${ev.date} ist möglicherweise ein ${w.ticketCapacity}er Teamtisch verfügbar. Melde dich gerne bei uns.`;const wa=whatsappLink(w.whatsapp,text);return `<div class="field-row"><div><strong>${esc(w.name)}</strong><small>${w.ticketCapacity}er Teamticket · ${esc(w.email)}<br>${esc(w.whatsapp||'Keine WhatsApp-Nummer')}</small></div><div class="actions"><a class="btn" href="mailto:${encodeURIComponent(w.email)}?subject=${encodeURIComponent(ev.title)}&body=${encodeURIComponent(text)}">E-Mail öffnen</a>${wa?`<a class="btn primary" href="${esc(wa)}" target="_blank" rel="noopener noreferrer">WhatsApp öffnen ↗</a>`:''}</div></div>`;}).join(''):'<p>Noch keine Wartelisteneinträge.</p>')}${card('Optionale Abläufe',`<p>Bevorzugtes Kaufrecht: <strong>${ev.settings.waitPriority?'Aktiv · '+ev.settings.offerHours+' Stunden':'Aus'}</strong></p><p>Alle passenden Wartenden benachrichtigen: <strong>${ev.settings.waitBroadcast?'Aktiv':'Aus'}</strong></p><a class="btn" href="#event/${ev.id}/settings">Regeln bearbeiten</a><p class="footnote">Bei beiden Optionen hat ein individuelles Kaufrecht Vorrang; Sammelbenachrichtigungen gelten nur für nicht reservierte Kapazität. Automatiken sind konfiguriert, aber benötigen den Versanddienst im Backend.</p>`)}<div class="hint">WhatsApp öffnet einen vorbereiteten Text. Du prüfst und sendest selbst; das Öffnen wird nicht als Versand gespeichert.</div>`;}
function mails(){const ev=event();$('#content').innerHTML=`<h2>E-MAILS & REMINDER.</h2>${card("Teamnamen ergänzen",`<p>Automatische Erinnerung: <strong>${ev.settings.nameReminder?ev.settings.reminderHours+" Stunden vor Beginn":"Aus"}</strong>. Namensfrist: ${ev.settings.nameCutoff} Stunden vor Beginn.</p><p>${orders().filter(o=>!o.team).length} Teams ohne Namen. Es werden nur weiterhin namenlose Teams berücksichtigt.</p><a class="btn" href="#event/${ev.id}/settings">Zeitpunkte einstellen</a><p class="footnote">Versandplanung als Vorschau. Keine E-Mails werden verschickt.</p>`)}${card('Vorlagen für diesen Abend',ev.mails.length?ev.mails.map(m=>`<div class="field-row"><div><strong>${esc(m.subject)}</strong><small class="subtle"> · ${esc(m.timing)} · nur Vorlage</small></div><button class="btn" data-mail="${m.id}">Bearbeiten</button></div>`).join(''):'<p>Keine Vorlagen angelegt.</p>')}<div class="two-col"><button class="template" data-mail-new="reminder"><span class="eyebrow">VOR DEM EVENT</span><strong>Erinnerung am Vortag</strong><small>Einlassinfos, Ticket und Quiz-Link.</small></button><button class="template" data-mail-new="thanks"><span class="eyebrow">NACH DEM EVENT</span><strong>Danke fürs Miträtseln</strong><small>Ergebnisse und gemeinsame Erinnerungen.</small></button></div><p class="footnote">Vorlagen werden lokal gespeichert. Zeitgesteuerter Versand, Empfängerprüfung und Zustellhistorie werden mit dem Backend angeschlossen.</p>`;}
function mailDialog(id,kind){const ev=event(),m=ev.mails.find(m=>m.id===id)||{subject:kind==='thanks'?'Danke fürs Miträtseln!':'Morgen ist euer Quizabend!',timing:kind==='thanks'?'1 Tag danach':'1 Tag vorher',text:'Hallo {customer_name},\nwir freuen uns auf euch!'};openDialog('E-MAIL-VORLAGE',`${field('Betreff *','subject',m.subject,'text','required maxlength="150"')}<div style="margin:20px 0">${field('Zeitpunkt relativ zum Event','timing',m.timing,'text','required maxlength="80"')}</div><label class="field"><span>Nachricht</span><textarea name="text" required maxlength="5000">${esc(m.text)}</textarea></label><p class="footnote">Platzhalter: {customer_name}, {event_name}. Kein Versand aus der Vorschau.</p>`,f=>{const row={id:id||uid(),subject:String(f.get('subject')),timing:String(f.get('timing')),text:String(f.get('text'))};if(id)ev.mails[ev.mails.findIndex(m=>m.id===id)]=row;else ev.mails.push(row);done('Vorlage lokal gespeichert – keine Mail versendet.');});}
function confirmation(){const ev=event(),c=ev.confirmation;$('#content').innerHTML=`<h2>BESTÄTIGUNG & DIGITALES TICKET.</h2><form id="confirm-form">${card('Inhalt der Bestätigung',`<label class="field"><span>Vorlage</span><select name="scope"><option value="event" ${c.scope==='event'?'selected':''}>Eigene Vorlage für dieses Event</option><option value="global" ${c.scope==='global'?'selected':''}>Globale Standardvorlage verwenden</option></select></label><div style="margin:20px 0">${field('Betreff *','subject',c.subject,'text','required maxlength="150"')}</div><label class="field"><span>Nachricht</span><textarea name="text" maxlength="5000" required>${esc(c.text)}</textarea></label><p class="footnote">Bei „global“ wird beim Speichern die Demo-Standardvorlage übernommen; eigene Eingaben gelten nur für dieses Event.</p>`)}${card('Was der Käufer bekommt',`<div class="form-grid">${check('Ticket-PDF als Anhang','pdf',c.pdf)}${check('Apple-Wallet-Link','apple',c.apple)}${check('Google-Wallet-Link','google',c.google)}</div><div class="hint">PDF, Wallet und Ausdruck verweisen auf dieselbe Ticketberechtigung. Wallet benötigt eigene signierte Pässe; die PDF wird nicht in einen Wallet-Pass umgewandelt. Im Erstumfang sind alle drei Ausgaben vorgesehen.</div>`)}${card('Bestätigungsmail · Vorschau',emailPreview())}${savebar()}</form>`;bindSave('#confirm-form',f=>{ev.confirmation=f.get('scope')==='global'?{...structuredClone(db.globalConfirmation),scope:'global'}:{scope:'event',subject:String(f.get('subject')),text:String(f.get('text')),pdf:f.has('pdf'),apple:f.has('apple'),google:f.has('google')};});}
function emailPreview(){const ev=event(),c=ev.confirmation;return `<article class="email-preview"><div class="brand">DER<span>KNEIPENKÖNIG</span></div><h2>EUER ABEND STEHT.</h2><p>${esc(c.text.replaceAll('{customer_name}','Alex').replaceAll('{event_name}',ev.title))}</p><div class="email-box"><strong>${esc(ev.title)}</strong><p>${ev.date.split('-').reverse().join('.')} · ${ev.start} Uhr<br>Einlass ${ev.doors} Uhr<br>${esc(ev.address)}<br>Team: Die Schlauberger · 6er Teamticket<br>Bestellung: DEMO-1001 · Zahlung: Demo bestätigt</p>${c.pdf?'<span class="badge">Anhang: Teamticket.pdf</span>':''}${c.apple?'<span class="badge">Apple Wallet · Vorschau</span>':''}${c.google?'<span class="badge">Google Wallet · Vorschau</span>':''}<p>Ticketcode: DEMO-1001 · Zum Quiz anmelden</p><small>Layout-Vorschau · kein PDF oder Wallet-Pass erzeugt · keine Nachricht versendet</small></div></article>`;}
function formView(){const ev=event();$('#content').innerHTML=`<h2>BUCHUNGSFORMULAR.</h2><form id="fields-form">${card('Angaben beim Ticketkauf',`<p class="subtle">Nur das Nötige abfragen. Name und E-Mail pro Bestellung; optionaler Teamname pro Teamticket.</p>${ev.fields.map(f=>`<div class="field-row"><span>${esc(f.label)} ${f.locked?'<small class="subtle">· Kernfeld</small>':''}</span><div class="actions">${check('Pflichtfeld','required:'+f.id,f.required)}${!f.locked?`<button type="button" class="link" data-remove-field="${f.id}">Entfernen</button>`:''}</div></div>`).join('')}`,btn('+ Feld ergänzen','field'))}${savebar()}</form><div style="margin-top:24px">${card('Formularvorschau',`<div class="form-preview">${ev.fields.map(f=>`<label class="field"><span>${esc(f.label)} ${f.required?'*':''}</span><input disabled placeholder="${esc(f.label)}"></label>`).join('')}</div>`)}</div>`;bindSave('#fields-form',f=>{ev.fields.forEach(x=>{x.required=x.id==='team'?false:(x.locked||f.has('required:'+x.id));});});document.querySelectorAll('#fields-form .check input').forEach(input=>{const x=ev.fields.find(x=>'required:'+x.id===input.name);if(x?.locked)input.disabled=true;});}
function quiz(){const ev=event();$('#content').innerHTML=`<h2>QUIZVORBEREITUNG.</h2>${card('Vom Ticket direkt zum Team',`<p>Teamnamen und Ticketgrößen werden aus den Bestellungen übernommen. Einlass und Quiz-Anmeldung bleiben getrennt.</p><div class="hint">Ziel: bestehende Quiz-App / Stammtisch. Die folgende Aktion simuliert nur die Übernahme und verbindet keine echte Session.</div>`,btn('Alle Teams übernehmen · Demo','sync',true))}<section class="card"><div class="table-wrap"><table><thead><tr><th>TEAM</th><th>TICKETGRÖSSE</th><th>LOCATION</th><th>QUIZ</th><th>EINLASS</th></tr></thead><tbody>${orders().map(o=>`<tr><td><strong>${esc(o.team)}</strong><small>${esc(o.id)}</small></td><td>${o.ticketCapacity}</td><td>${esc(ev.venue)}</td><td><span class="status ${o.quiz?'':'draft'}">${o.quiz?'Übernommen · Demo':'Noch offen'}</span></td><td>${o.checked?'✓ Vor Ort':'Nicht eingecheckt'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Noch keine Teams gebucht.</td></tr>'}</tbody></table></div></section>`;}
function exportCsv(){const ev=event(),safe=v=>{const s=String(v??'');return '"'+(/^[=+@\-]/.test(s)?"'":'')+s.replaceAll('"','""')+'"';};const rows=[['Bestellung','Team','Name','Personen','Ticketart','Eingecheckt'],...orders().map(o=>[o.id,o.team,o.name,o.ticketCapacity,ev.tickets.find(t=>t.id===o.typeId)?.name,o.checked?'Ja':'Nein'])];const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='einlassliste-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function render(){assignFallbacks(db);const [route,id,view]=location.hash.slice(1).split('/');document.querySelectorAll('.top nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===(route==='settings'?'#settings':route==='overview'?'#overview':'#events')));if(route==='settings'){settingsView(true);return;}if(route==='event'&&db.events.some(ev=>ev.id===id)){selected=id;tab=view||'summary';shell();}else dashboard(route==='overview');}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(dirty&&(b.dataset.ticket!==undefined||b.dataset.group!==undefined||b.dataset.bundle!==undefined||b.dataset.action)&&!confirm('Ungespeicherte Formulareingaben verwerfen und Aktion öffnen?'))return;if(dirty&&b.type==='button'){dirty=false;render();}if(b.dataset.teamEdit){const o=db.orders.find(o=>o.id===b.dataset.teamEdit);openDialog('TEAMNAME ÄNDERN',field('Teamname','team',o.team,'text','maxlength="20"'),f=>{o.team=validateName(db,o.eventId,f.get('team'),o.id);o.autoName=false;assignFallbacks(db);done('Teamname aktualisiert.');});return;}if(b.dataset.scope){scope=b.dataset.scope;dashboard();return;}if(b.dataset.duplicate){duplicate(db.events.find(ev=>ev.id===b.dataset.duplicate));return;}if(b.dataset.ticket){ticketDialog(b.dataset.ticket);return;}if(b.dataset.group){groupDialog(b.dataset.group);return;}if(b.dataset.bundle){bundleDialog(b.dataset.bundle);return;}if(b.dataset.mail){mailDialog(b.dataset.mail);return;}if(b.dataset.mailNew){mailDialog(null,b.dataset.mailNew);return;}if(b.dataset.check){const o=db.orders.find(o=>o.id===b.dataset.check);o.checked=!o.checked;persist();orderView();toast(o.checked?'Demo-Check-in erfasst.':'Demo-Check-in zurückgesetzt.');return;}if(b.dataset.offer!==undefined){db.waiters[Number(b.dataset.offer)].offered=true;persist();waitlist();toast('Angebot simuliert. Keine Mail versendet.');return;}if(b.dataset.removeField){event().fields=event().fields.filter(f=>f.id!==b.dataset.removeField||f.locked);persist();formView();return;}const ev=event();switch(b.dataset.action){case 'new':{const blank=structuredClone(base);Object.assign(blank,{settings:structuredClone(db.settings),fields:structuredClone(db.globalFields).filter(f=>f.id!=='size').map(f=>({...f,required:f.id==='team'?false:f.required})),id:uid(),title:'Neuer Quizabend',date:'2026-11-01',status:'draft',tickets:[],groups:[],bundles:[],mails:[],saleStart:'',saleEnd:''});db.events.push(blank);persist();navigate('event/'+blank.id+'/edit');break;}case 'duplicate':duplicate(ev);break;case 'ticket':ticketDialog();break;case 'group':groupDialog();break;case 'bundle':bundleDialog();break;case 'order':orderDialog();break;case 'export':exportCsv();break;case 'print':window.print();break;case 'pause':ev.status='paused';persist();render();toast('Demo-Verkauf pausiert.');break;case 'publish':if(!ev.tickets.length||!ev.saleStart||!ev.saleEnd){toast('Vor Veröffentlichung Ticketart und Verkaufszeitraum festlegen.');break;}ev.status='published';persist();render();toast('Event in der Demo veröffentlicht.');break;case 'copy':navigator.clipboard.writeText(location.origin+location.pathname+'#event/'+ev.id+'/summary').then(()=>toast('Lokalen Vorschaulink kopiert.')).catch(()=>toast('Kopieren nicht möglich. Link bitte markieren.'));break;case 'sync':orders().forEach(o=>o.quiz=true);persist();quiz();toast('Teams lokal übernommen – keine externe Verbindung.');break;case 'preview':openDialog('EVENTVORSCHAU',`<span class="eyebrow">${esc(ev.venue)}</span><h2>${esc(ev.title)}</h2><p>${ev.date.split('-').reverse().join('.')} · ${ev.start} Uhr</p><p>${esc(ev.description)}</p>${ev.tickets.map(t=>`<div class="field-row"><strong>${esc(t.name)}</strong><span>${money(t.price)}</span></div>`).join('')}<div class="hint">Vorschau der gespeicherten Eventdaten. Verkauf und Manager verwenden denselben lokalen Datenbestand.</div>`,()=>drawer.close(),'Schließen');break;case 'field':openDialog('FORMULARFELD',field('Feldbezeichnung *','label','','text','required maxlength="80"'),f=>{ev.fields.push({id:uid(),label:String(f.get('label')).trim(),required:false,locked:false});done('Textfeld ergänzt.');});break;}});
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&dirty){if(!confirm('Ungespeicherte Änderungen verwerfen?')){e.preventDefault();return;}dirty=false;}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{render();app.focus();window.scrollTo(0,0);});
$('#reset').onclick=()=>{if(!confirm('Lokale Demo-Änderungen zurücksetzen?'))return;localStorage.removeItem(KEY);db=loadDB();dirty=false;persist();location.hash='events';render();toast('Demo zurückgesetzt.');};
render();

document.addEventListener('keydown', e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){const form=document.querySelector('#content form');if(form&&!drawer.open){e.preventDefault();form.requestSubmit();}}if(e.key==='/'&&!drawer.open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){const search=document.querySelector('#search, #order-search');if(search){e.preventDefault();search.focus();}}});


function settingsFields(v){return `<div class="form-grid">${field('Maximale Teamtickets je Bestellung','maxTickets',v.maxTickets,'number','min="1" max="100" required')}${check('Check-in vor Quiz-Anmeldung erforderlich','checkin',v.checkin)}${field('Teamnamen ändern bis … Stunden vor Beginn','nameCutoff',v.nameCutoff,'number','min="0" max="8760" required')}${check('Teams ohne Namen automatisch erinnern','nameReminder',v.nameReminder)}${field('Erinnerung … Stunden vor Beginn','reminderHours',v.reminderHours,'number','min="0" max="8760" required')}${check('Warteliste: bevorzugtes Kaufrecht','waitPriority',v.waitPriority)}${field('Kaufrecht gültig für … Stunden','offerHours',v.offerHours,'number','min="1" max="8760" required')}${check('Warteliste: alle passenden Wartenden benachrichtigen','waitBroadcast',v.waitBroadcast)}</div>`;}
function settingsView(global=false){const target=global?app:$('#content'),v=global?db.settings:event().settings;target.innerHTML=`<h2>${global?'GLOBALE VORGABEN.':'TEILNAHME & REGELN.'}</h2><p class="subtle">${global?'Gelten für neu erstellte Events. Bestehende Veranstaltungen bleiben unverändert.':'Diese Einstellungen gelten nur für diesen Quizabend.'}</p><form id="rules-form">${card('Teams, Fristen & Warteliste',settingsFields(v))}<div class="hint">Alle Fristen beziehen sich auf den Quizbeginn in Europe/Berlin. 24 Stunden = 1 Tag. Nach Fristende erhalten namenlose Teams einen eindeutigen Ersatznamen. Offene Barzahlung verhindert den Check-in nicht.</div>${!global?'<button type="button" class="btn" id="apply-defaults">Aktuelle globale Vorgaben ins Formular übernehmen</button>':''}${savebar()}</form>`;bindSave('#rules-form',f=>{const next={};for(const k of ['maxTickets','nameCutoff','reminderHours','offerHours'])next[k]=Number(f.get(k));for(const k of ['checkin','nameReminder','waitPriority','waitBroadcast'])next[k]=f.has(k);validateSettings(next);if(next.maxTickets>100)throw Error('Maximal 100 Teamtickets pro Bestellung.');if(global)db.settings=next;else event().settings=next;});$('#apply-defaults')?.addEventListener('click',()=>{for(const [k,v] of Object.entries(db.settings)){const el=$('#rules-form').elements[k];if(typeof v==='boolean')el.checked=v;else el.value=v;}dirty=true;$('#save-status').textContent='Vorgaben übernommen – zum Anwenden speichern';});}
window.addEventListener('storage',e=>{if(e.key===KEY&&!dirty&&!drawer.open){db=loadDB();render();}});
setInterval(()=>{if(!dirty&&!drawer.open&&assignFallbacks(db)){persist();render();}},30000);

persist();
